			rl, rm = _split7(t[r, 'r'].val)
			gl, gm = _split7(t[r, 'g'].val)
			bl, bm = _split7(t[r, 'b'].val)
			wl, wm = _split7(t[r, 'w'].val)
			self.SendExclusive(0x00, 0x21, 0x1D, 0x01, 0x01, 0x03, idx,
