		"""Steps 1-9 of DESIGN.md 5. Step 10 (REST bootstrap) and step 11 (full LED
		redraw) are driven by the orchestrator once ResolumeState/LedPainter exist."""
		self.BindDevice()
		self.DeviceInquiry()
		self.SetMode('user')
		self.SetAftertouch()
		self.SetLedBrightness()
		self.SetDisplayBrightness()
		self.WritePalette()
		self.ReapplyPalette()
