FRAME_HEADER = bytes([0xFF, 0xCC, 0xAA, 0x88]) + bytes(12)
LINE_WIDTH_PX = 960
LINE_COUNT = 160
LINE_PIXEL_BYTES = LINE_WIDTH_PX * 2  # RGB565
